<template>
  <div data-sales-configuration-page>
    <PageHead title="销售配置" desc="维护可复用选配方案，以及模型和商品的销售范围。"><el-button @click="router.push('/sales-shopping')">进入销售选购</el-button><el-dropdown trigger="click"><el-button>更多配置</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="router.push('/compatibility')">商品适用关系</el-dropdown-item><el-dropdown-item @click="router.push('/benefit-packages')">常用组合</el-dropdown-item><el-dropdown-item @click="router.push('/specs')">模型范围设置</el-dropdown-item></el-dropdown-menu></template></el-dropdown></PageHead>
    <section class="panel">
      <el-tabs v-model="tab"><el-tab-pane label="选配方案" name="plans"/><el-tab-pane label="范围绑定" name="bindings"/><el-tab-pane label="商品关联" name="relations"/></el-tabs>
      <div class="toolbar"><el-input v-model="search" clearable placeholder="搜索名称或来源" aria-label="搜索销售配置"/><template v-if="tab==='plans'"><el-button v-if="store.can('product:sales-config:create')" type="primary" data-sales-new-plan @click="editPlan()">新建选配方案</el-button></template><template v-else-if="tab==='bindings'"><el-button v-if="store.can('product:sales-config:update')" type="primary" data-sales-new-binding @click="editBinding()">新增范围绑定</el-button><el-button v-if="store.can('product:sales-config:publish')" :disabled="!selectedBindings.length" @click="previewUpgrade">预览所选绑定升级</el-button></template><el-button v-else-if="store.can('product:compatibility:create')" type="primary" data-sales-new-relation @click="editRelation()">新增商品关联</el-button></div>
      <el-table v-if="tab==='plans'" :data="plans" row-key="id" data-sales-plan-table>
        <el-table-column label="方案" min-width="200"><template #default="{row}"><button class="linkish" @click="editPlan(row.id)">{{row.name}}</button></template></el-table-column>
        <el-table-column label="状态" width="140"><template #default="{row}"><el-tag :type="row.status==='available'?'success':row.status==='disabled'?'info':'warning'">{{statusLabel(row.status)}}</el-tag></template></el-table-column>
        <el-table-column label="发布版本" width="125"><template #default="{row}">{{row.publishedVersion?`v${row.publishedVersion}`:'尚未发布'}}</template></el-table-column>
        <el-table-column label="选配项目" width="110"><template #default="{row}">{{row.items.filter((item:SalesOptionItem)=>item.enabled).length}}</template></el-table-column>
        <el-table-column label="使用范围" width="120"><template #default="{row}"><el-button link @click="showUsages(row.id)">{{usageCount(row.id)}} 项绑定</el-button></template></el-table-column>
        <el-table-column label="操作" min-width="230"><template #default="{row}"><el-button link @click="editPlan(row.id)">编辑</el-button><el-button v-if="store.can('product:sales-config:publish')" link type="primary" :disabled="busy" @click="openPublish(row)">发布版本</el-button><el-dropdown trigger="click"><el-button link :disabled="busy" :aria-label="`${row.name}更多操作`">更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="store.can('product:sales-config:create')" @click="copyPlan(row.id)">复制方案</el-dropdown-item><el-dropdown-item v-if="store.can('product:sales-config:publish')" :disabled="row.status!=='available'&&!row.publishedVersion" @click="setStatus(row)">{{row.status==='available'?'停用方案':'启用方案'}}</el-dropdown-item><el-dropdown-item @click="showUsages(row.id)">查看使用范围</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
      </el-table>
      <template v-else-if="tab==='bindings'"><div v-if="usagePlanId" class="usage-filter"><span>方案：{{planName(usagePlanId)}}</span><el-button link @click="usagePlanId=''">查看全部绑定</el-button></div><el-table :data="bindings" row-key="id" @selection-change="selectedBindings=$event" data-sales-binding-table><el-table-column type="selection" width="42"/><el-table-column label="范围" min-width="230"><template #default="{row}"><button class="linkish" @click="editBinding(row.id)">{{row.name||bindingLabel(row)}}</button><div class="muted">{{bindingLabel(row)}}</div></template></el-table-column><el-table-column label="匹配方案" min-width="200"><template #default="{row}">{{row.mode==='none'?'不使用方案':`${planName(row.planId)} · v${row.planVersion||'未发布'}`}}<div class="muted">{{row.mode==='default'?'默认':row.mode==='replace'?'完整替换':'只关闭选配展示'}}</div></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'已启用':'草稿 / 停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link @click="editBinding(row.id)">查看 / 调整</el-button><el-button v-if="store.can('product:sales-config:update')&&row.enabled" link :disabled="busy||!canDisableBinding(row)" :title="canDisableBinding(row)?undefined:'停用正式绑定需要发布权限'" @click="disableBinding(row)">停用</el-button></template></el-table-column></el-table></template>
      <el-table v-else :data="relations" row-key="id" data-sales-relation-table><el-table-column label="来源商品" min-width="220"><template #default="{row}">{{skuName(row.sourceSkuId)}}</template></el-table-column><el-table-column label="相关商品" min-width="220"><template #default="{row}">{{skuName(row.targetSkuId)}}</template></el-table-column><el-table-column label="用途" width="130"><template #default="{row}">{{row.kind==='recommendation'?'搭配推荐':'直接适用声明'}}</template></el-table-column><el-table-column label="状态" width="160"><template #default="{row}">{{!row.enabled?'停用':row.kind==='recommendation'?'只做推荐':row.verification==='pending'?'待核验':row.conclusion==='incompatible'?'明确不适用':row.conclusion==='conditional'?'有条件适用':'已核验适用'}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link @click="editRelation(row.id)">查看 / 编辑</el-button></template></el-table-column></el-table>
      <el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><details v-if="unknownRows.length" class="unknown-records"><summary>不支持的配置版本 · {{unknownRows.length}} 条，只读保留</summary><p v-for="row in unknownRows" :key="row.key">{{row.label}} · {{row.id}} · 版本 {{row.version}}</p></details>
    </section>
    <SalesPlanEditor v-model="planOpen" :plan-id="planId" :copy-id="copyId" @saved="savedPlan"/>
    <SalesBindingDialog v-model="bindingOpen" :binding-id="bindingId"/>
    <SalesProductRelationEditor v-model="relationOpen" :relation-id="relationId"/>
    <el-dialog v-model="publishOpen" title="发布选配方案" width="min(680px,96vw)" :close-on-click-modal="false" :show-close="!busy" data-sales-publish-dialog><template v-if="publishPlan"><p>发布「{{publishPlan.name}}」的新版本。现有 {{usageCount(publishPlan.id)}} 项绑定继续使用原版本。</p><el-table :data="(store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion===1&&item.planId===publishPlan?.id)" size="small"><el-table-column prop="name" label="已绑定范围"/><el-table-column label="现用版本" width="120"><template #default="{row}">v{{row.planVersion}}</template></el-table-column></el-table><p class="muted">发布后，在“范围绑定”选择需要升级的范围，核对影响后再应用。</p></template><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="publishOpen=false">取消</el-button><el-button type="primary" :loading="busy" data-sales-confirm-publish @click="publish">发布新版本</el-button></template></el-dialog>
    <el-dialog v-model="upgradeOpen" title="核对绑定版本更新" width="min(800px,96vw)" :close-on-click-modal="false" :show-close="!busy" data-sales-upgrade-preview><article v-for="row in upgrades" :key="row.draft.id" class="upgrade-row"><strong>{{row.draft.name||bindingLabel(row.draft)}}</strong><span>v{{row.before}} → v{{row.draft.planVersion}}</span><span>合法规格 {{row.preview.legalCount}} · 当前销售 SKU {{row.preview.skuCount}}</span><p v-for="issue in row.preview.issues" :key="issue" class="warn">{{issue}}</p><p v-for="item in row.preview.unresolved" :key="item.id" class="warn">{{item.id}}：{{item.message}}</p></article><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button :disabled="busy" @click="upgradeOpen=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!upgrades.length||upgrades.some(row=>row.draft.enabled&&!row.preview.canApply)" data-sales-confirm-upgrade @click="applyUpgrade">确认更新所选绑定</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import PageHead from '../components/PageHead.vue'
import SalesPlanEditor from '../components/sales-configuration/SalesPlanEditor.vue'
import SalesBindingDialog from '../components/sales-configuration/SalesBindingDialog.vue'
import SalesProductRelationEditor from '../components/sales-configuration/SalesProductRelationEditor.vue'
import {useCatalogStore,uid} from '../stores/catalog'
import {previewSalesBinding} from '../domain/salesConfiguration'
import {commandPermissions} from '../domain/rbac'
import {savedSkuName} from '../domain/productList'
import type {SalesOptionItem,SalesOptionPlan,SalesOptionBinding,SalesBindingPreview} from '../domain/salesConfigurationTypes'
const store=useCatalogStore(),router=useRouter(),tab=ref('plans'),search=ref(''),error=ref(''),busy=ref(false),usagePlanId=ref('')
const planOpen=ref(false),planId=ref(''),copyId=ref(''),bindingOpen=ref(false),bindingId=ref(''),relationOpen=ref(false),relationId=ref(''),publishOpen=ref(false),publishPlan=ref<SalesOptionPlan>(),selectedBindings=ref<SalesOptionBinding[]>([]),upgradeOpen=ref(false),upgrades=ref<{draft:SalesOptionBinding;before:number|null;preview:SalesBindingPreview}[]>([])
let alive=true,publishRequest='',upgradeRequest=''
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const needle=computed(()=>search.value.trim().toLocaleLowerCase())
const plans=computed(()=>(store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion===1&&item.name.toLocaleLowerCase().includes(needle.value)))
const bindings=computed(()=>(store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion===1&&(!usagePlanId.value||item.planId===usagePlanId.value)&&`${item.name} ${bindingLabel(item)} ${planName(item.planId)}`.toLocaleLowerCase().includes(needle.value)))
const relations=computed(()=>(store.data.salesProductRelations||[]).filter(item=>item.schemaVersion===1&&`${skuName(item.sourceSkuId)} ${skuName(item.targetSkuId)} ${item.source}`.toLocaleLowerCase().includes(needle.value)))
const unknownRows=computed(()=>[...(store.data.salesOptionPlans||[]).filter(item=>item.schemaVersion!==1).map(item=>({key:'plan:'+item.id,label:'选配方案',id:item.id,version:item.schemaVersion})),...(store.data.salesOptionBindings||[]).filter(item=>item.schemaVersion!==1).map(item=>({key:'binding:'+item.id,label:'范围绑定',id:item.id,version:item.schemaVersion})),...(store.data.salesProductRelations||[]).filter(item=>item.schemaVersion!==1).map(item=>({key:'relation:'+item.id,label:'商品关联',id:item.id,version:item.schemaVersion}))])
const statusLabel=(status:string)=>({draft:'草稿',available:'已发布 / 启用',disabled:'已停用'})[status]||'未知版本'
const planName=(id:string|null)=>store.data.salesOptionPlans?.find(item=>item.id===id)?.name||'方案引用失效'
const skuName=(id:string)=>{const sku=store.data.skus.find(item=>item.id===id);return sku?savedSkuName(sku):`SKU 已不存在：${id}`}
function usageCount(id:string){return store.data.salesOptionBindings?.filter(item=>item.schemaVersion===1&&item.planId===id).length||0}
function bindingLabel(binding:SalesOptionBinding){if(binding.scope.kind==='products')return `指定 ${binding.scope.familyIds.length} 款商品 / ${binding.scope.skuIds.length} 条 SKU`;const scope=binding.scope;const name=store.data.specCanvases.find(item=>item.templateId===scope.modelId)?.name||scope.modelId;const version=store.data.specModelVersions.find(item=>item.id===scope.versionId);return `${name} · ${version?.versionName||(!scope.versionId?'模型草稿':'版本失效')}${scope.nodeId?' · 节点范围':scope.selector?' · 条件范围':''}`}
function editPlan(id=''){copyId.value='';planId.value=id;planOpen.value=true}
function copyPlan(id:string){planId.value='';copyId.value=id;planOpen.value=true}
function editBinding(id=''){bindingId.value=id;bindingOpen.value=true}
function editRelation(id=''){relationId.value=id;relationOpen.value=true}
function showUsages(id:string){usagePlanId.value=id;search.value='';tab.value='bindings'}
function savedPlan(){ElMessage.success('选配方案草稿已保存')}
function ownerGuard(){const actor=store.activeUserId,preview=store.previewUserId;return()=>alive&&actor===store.activeUserId&&preview===store.previewUserId}
function openPublish(plan:SalesOptionPlan){publishPlan.value=clone(plan);publishRequest=uid('sales-publish');error.value='';publishOpen.value=true}
async function publish(){if(!publishPlan.value||busy.value)return;const guard=ownerGuard();busy.value=true;error.value='';try{const result=await store.publishSalesOptionPlan({id:publishPlan.value.id,expectedRevision:publishPlan.value.revision,requestId:publishRequest},guard);if(!result.ok){error.value=result.message||'发布失败，原版本保留。';return}publishOpen.value=false;ElMessage.success('已发布新版本；现有绑定版本保持不变')}catch(cause){error.value=String(cause)}finally{busy.value=false}}
async function setStatus(plan:SalesOptionPlan){if(busy.value)return;const guard=ownerGuard(),status=plan.status==='available'?'disabled':'available';try{await ElMessageBox.confirm(`${status==='disabled'?'停用':'启用'}「${plan.name}」？关联范围中的新选购会按此状态重新核对。`,'方案状态')}catch{return}if(!guard()){error.value='操作者或配置上下文已变化，请重新核对后操作。';return}busy.value=true;error.value='';try{const result=await store.setSalesOptionPlanStatus({id:plan.id,status,expectedRevision:plan.revision,requestId:uid('sales-status')},guard);if(!result.ok)error.value=result.message||'状态没有保存。'}catch(cause){error.value=String(cause)}finally{busy.value=false}}
function canDisableBinding(binding:SalesOptionBinding){return commandPermissions('saveSalesOptionBinding',[{draft:{...binding,enabled:false}}],store.data).every(store.can)}
async function disableBinding(binding:SalesOptionBinding){if(busy.value||!canDisableBinding(binding))return;const draft={...clone(binding),enabled:false};busy.value=true;error.value='';try{const result=await store.saveSalesOptionBinding({draft,expectedRevision:binding.revision,expectedBasis:previewSalesBinding(store.data,draft).stamp,requestId:uid('sales-disable')},ownerGuard());if(!result.ok)error.value=result.message||'停用失败。'}catch(cause){error.value=String(cause)}finally{busy.value=false}}
function previewUpgrade(){
  error.value='';upgrades.value=[]
  const changes=selectedBindings.value.flatMap(binding=>{const plan=store.data.salesOptionPlans?.find(item=>item.schemaVersion===1&&item.id===binding.planId);if(binding.mode==='none'||!plan?.publishedVersion||plan.publishedVersion===binding.planVersion)return [];return [{draft:{...clone(binding),planVersion:plan.publishedVersion},before:binding.planVersion}]})
  const joint={...store.data,salesOptionBindings:[...(store.data.salesOptionBindings||[]).filter(item=>!changes.some(change=>change.draft.id===item.id)),...changes.map(change=>change.draft)]}
  upgrades.value=changes.map(change=>({...change,preview:{...previewSalesBinding(joint,change.draft),stamp:previewSalesBinding(store.data,change.draft).stamp}}))
  upgradeRequest=uid('sales-bindings-upgrade');upgradeOpen.value=true
  if(!upgrades.value.length)error.value='所选绑定已是最新发布版本，或未引用已发布方案。'
}
async function applyUpgrade(){if(busy.value||!upgrades.value.length)return;busy.value=true;error.value='';try{const result=await store.saveSalesOptionBindings({drafts:upgrades.value.map(row=>row.draft),expectedRevisions:Object.fromEntries(upgrades.value.map(row=>[row.draft.id,row.draft.revision])),expectedBasis:Object.fromEntries(upgrades.value.map(row=>[row.draft.id,row.preview.stamp])),requestId:upgradeRequest},ownerGuard());if(!result.ok){error.value=result.message||'批量更新未完成，原绑定保持。';return}upgradeOpen.value=false;ElMessage.success('所选绑定已更新')}catch(cause){error.value=String(cause)}finally{busy.value=false}}
onBeforeUnmount(()=>{alive=false})
</script>
<style scoped>.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:6px 0 16px}.toolbar>.el-input{width:280px;max-width:100%}.linkish{border:0;background:none;color:var(--el-color-primary);font:inherit;cursor:pointer;padding:0;text-align:left}.muted{color:var(--el-text-color-secondary);font-size:12px}.usage-filter{display:flex;align-items:center;gap:12px;margin-bottom:10px}.upgrade-row{display:flex;gap:12px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--el-border-color-lighter)}.upgrade-row .warn{width:100%;color:var(--el-color-danger);margin:0}.panel{overflow:hidden}.panel>.el-alert{margin-top:14px}</style>
